@router.get({{path}}, response_model=list[ParentRead])
async def list_parent(page_size: Annotated[int, Query(alias="limit", ge=1, le={{max_limit}})] = 20, offset: Annotated[int, Query(ge=0)] = 0) -> list[Parent]:
    """List parent."""
    filters: dict[str, object] = {}
    return await Parent.find(filters).sort("_id").skip(offset).limit(page_size).to_list()
